1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import java.util.stream.Collectors;
6	import net.officefloor.web.HttpPathParameter;
7	import net.officefloor.web.HttpQueryParameter;
8	import net.officefloor.web.ObjectResponse;
9	
10	/**
11	 * GET /api/projects/{projectId}/invoices — a project's invoices. Ordered oldest first by default;
12	 * {@code ?sort=due} orders them by their due date, earliest first (id as a stable tie-breaker).
13	 */
14	public class ListInvoicesLogic {
15	
16	    public void service(@HttpPathParameter("projectId") String projectId,
17	            @HttpQueryParameter("sort") String sort, InvoiceRepository invoices,
18	            PaymentRepository payments, ObjectResponse<List<InvoiceView>> response) {
19	        Long id = Long.valueOf(projectId);
20	        List<Invoice> ordered = "due".equals(sort)
21	                ? invoices.findByProjectIdOrderByDueDateAscIdAsc(id)
22	                : invoices.findByProjectIdOrderByIdAsc(id);
23	        List<InvoiceView> views = ordered.stream()
24	                .map(inv -> {
25	                    // What is still left to pay: the billed amount minus everything paid so far.
26	                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(inv.getId()).stream()
27	                            .map(Payment::getAmount)
28	                            .reduce(BigDecimal.ZERO, BigDecimal::add);
