3	import java.io.IOException;
4	import java.io.UncheckedIOException;
5	import java.nio.charset.StandardCharsets;
6	import java.nio.file.Files;
7	import java.nio.file.Path;
8	import java.nio.file.StandardOpenOption;
9	import org.springframework.beans.factory.annotation.Value;
10	import org.springframework.stereotype.Service;
11	
12	/**
13	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
14	 * so tests can assert side-effects by reading that file — the second test-assertion channel
15	 * alongside the UI (DESIGN.md §3, docs/SUT_CONTRACT.md §4). The file path + one-record-per-line
16	 * format is a declared, stable contract, like data-testid: features may be rewritten as long as
17	 * they keep emitting the agreed records.
18	 *
19	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
20	 * SYNC) so a test reads the record immediately.
21	 */
22	@Service
23	public class Audit {
24	
25	    private final Path file;
26	
27	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
28	        this.file = Path.of(path);
29	    }
30	
31	    /** Append one audit record. Checkpoints assert the exact line(s) in the file. */
32	    public synchronized void record(String entry) {
33	        try {
34	            Path parent = file.toAbsolutePath().getParent();
35	            if (parent != null) {
36	                Files.createDirectories(parent);
37	            }
38	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
39	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
40	        } catch (IOException e) {
41	            throw new UncheckedIOException(e);
42	        }
43	    }
44	
45	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
46	    public synchronized void clear() {
47	        try {
48	            Files.deleteIfExists(file);
49	        } catch (IOException e) {
50	            throw new UncheckedIOException(e);
51	        }
52	    }
53	}
